{"file_path":"tests/test_spec.py","content":""""Regression coverage for the behavior defined in SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [event("a", 1, True), event("b", 1, False), event("c", 1, None)]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([event("c", 1, None)]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 1, None), event("d", 2, True)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 5, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "  # ignored,not a day,1", " a , 2 , 1 \n",
             "b, -3, 0", "\t c , 4 , \n", "# trailing comment"]
    assert parse_transcript_log(iter(lines)) == [
        event("a", 2, True), event("b", -3, False), event("c", 4, None),
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 5\b"):
        parse_transcript_log(["", " # comment", "a,1,1", " \t", bad_line])


def test_dedupe_transcripts_last_duplicate_id_wins_and_result_is_sorted():
    events = [
        event("b", 0, True), event("a", 2, True), event("c", 1, None),
        event("b", 2, False), event("a", 2, None), event("c", -1, True),
    ]
    assert dedupe_transcripts(events) == [events[5], events[4], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_dense_range():
    events = [
        event("before", 0, True), event("a", 1, True), event("b", 1, True),
        event("c", 2, False), event("d", 2, None), event("e", 4, True),
        event("after", 5, True),
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []


def test_daily_flag_counts_empty_and_negative_days():
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts([event("a", -1, True)], -2, 0) == [0, 1, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 0), (3, 1), (20, 1)])
def test_monitor_summary_pooled_rounding_calendar_window_and_nonempty_groups(days, recent):
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 3, False), event("c", 3, None)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_sorts_ties_by_name():
    groups = {
        "z": [event("a", 1, True), event("b", 1, False)],
        "empty": [],
        "a": [event("c", 1, True), event("d", 1, None)],
        "highest": [event("e", 1, True)],
        "lowest": [event("f", 1, False)],
    }
    assert top_flagged_groups(groups, 3) == ["highest", "a", "z"]
    assert top_flagged_groups(groups, 10) == ["highest", "a", "z", "lowest"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 3) == []
    assert top_flagged_groups({"empty": []}, 3) == []


def test_flag_rate_by_group_sorted_keys_and_empty_group_none():
    groups = {
        "z": [event("a", 1, True), event("b", 1, None)],
        "empty": [],
        "a": [event("c", 1, False)],
    }
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "empty", "z"]
    assert rates == {"a": 0.0, "empty": None, "z": 0.5}
    assert flag_rate_by_group({}) == {}


